BEGIN;
CREATE OR REPLACE FUNCTION public.get_landing_nearby_reports(p_lat double precision,p_lon double precision,p_rayon_m double precision DEFAULT 2000,p_limit integer DEFAULT 5) RETURNS TABLE(id uuid,service_type text,report_category text,commune text,quartier text,description text,created_at timestamptz,verifications integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public','extensions' AS $$ SELECT r.id,r.service_type,r.report_category,r.commune,r.quartier,left(r.description,200),r.created_at,r.verifications FROM public.reports r WHERE r.validated=true AND r.status='active' AND r.latitude IS NOT NULL AND r.longitude IS NOT NULL AND extensions.ST_DWithin(extensions.ST_SetSRID(extensions.ST_MakePoint(public.public_shift_coordinate(r.id,r.longitude,'lon'),public.public_shift_coordinate(r.id,r.latitude,'lat')),4326)::extensions.geography,extensions.ST_SetSRID(extensions.ST_MakePoint(p_lon,p_lat),4326)::extensions.geography,least(greatest(p_rayon_m,100),2000)) ORDER BY extensions.ST_Distance(extensions.ST_SetSRID(extensions.ST_MakePoint(public.public_shift_coordinate(r.id,r.longitude,'lon'),public.public_shift_coordinate(r.id,r.latitude,'lat')),4326)::extensions.geography,extensions.ST_SetSRID(extensions.ST_MakePoint(p_lon,p_lat),4326)::extensions.geography) ASC LIMIT least(greatest(p_limit,1),20); $$;
CREATE OR REPLACE FUNCTION public.get_nearby_reports(p_lat double precision,p_lon double precision,p_rayon_m double precision DEFAULT 200) RETURNS TABLE(id uuid,service_type text,description text,commune text,distance_m double precision,nb_verifications integer,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT r.id,r.service_type,left(r.description,100),r.commune,(6371000*acos(cos(radians(p_lat))*cos(radians(public.public_shift_coordinate(r.id,r.latitude,'lat')))*cos(radians(public.public_shift_coordinate(r.id,r.longitude,'lon'))-radians(p_lon))+sin(radians(p_lat))*sin(radians(public.public_shift_coordinate(r.id,r.latitude,'lat'))))),r.verifications,r.created_at FROM public.reports r WHERE r.status='active' AND r.validated=true AND r.latitude IS NOT NULL AND r.longitude IS NOT NULL AND (6371000*acos(cos(radians(p_lat))*cos(radians(public.public_shift_coordinate(r.id,r.latitude,'lat')))*cos(radians(public.public_shift_coordinate(r.id,r.longitude,'lon'))-radians(p_lon))+sin(radians(p_lat))*sin(radians(public.public_shift_coordinate(r.id,r.latitude,'lat'))))) <= least(greatest(p_rayon_m,100),500) ORDER BY distance_m ASC LIMIT 20; $$;
COMMIT;
